import React, { useState, useEffect } from "react";
import UserProfileCard from "./UserProfileCard";

export default function NgoDashboard({ token }) {
  const API = process.env.REACT_APP_API || "http://localhost:4000";

  const [me, setMe] = useState(null);
  const [ngoStats, setNgoStats] = useState(null);
  const [events, setEvents] = useState([]);

  // FETCH LOGGED USER DATA
  useEffect(() => {
    if (!token) return;

    (async () => {
      const res = await fetch(API + "/auth/me", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const d = await res.json();
      setMe(d);
    })();
  }, [token]);


  // FETCH NGO STATS
  useEffect(() => {
    if (!token) return;

    (async () => {
      const res = await fetch(API + "/api/ngo/achievements", {
        headers: { Authorization: `Bearer ${token}` },
      });
      const d = await res.json();

      if (d?.totals) {
        setNgoStats({
          totalEvents: d.totals.totalEvents,
          totalVolunteers: d.totals.totalVolunteers,
          totalDonations: d.totals.totalDonations,
          successfulEvents: d.successfulEvents,
          topEvents: d.topEvents || [],
        });
      }
    })();
  }, [token]);

  return (
    <div style={{ display: "flex", gap: 20 }}>

      {/* LEFT SIDE PROFILE */}
      <div style={{ width: 320 }}>
        {me ? <UserProfileCard me={me} /> : <p>Loading profile...</p>}

        {ngoStats && (
          <div
            style={{
              marginTop: 16,
              background: "#f8fbff",
              padding: 16,
              borderRadius: 12,
              border: "2px solid #2196F3",
            }}
          >
            <h4 style={{ marginBottom: 12, color: "#0b65c2" }}>NGO Overview</h4>

            <p><strong>Total Events:</strong> {ngoStats.totalEvents}</p>
            <p><strong>Total Volunteers:</strong> {ngoStats.totalVolunteers}</p>
            <p><strong>Total Donations:</strong> ₹{ngoStats.totalDonations}</p>
            <p><strong>Successful Events:</strong> {ngoStats.successfulEvents}</p>
          </div>
        )}
      </div>

      {/* RIGHT SIDE MAIN PANEL */}
      <div style={{ flex: 1 }}>
        <h3>NGO Dashboard</h3>

        {/* TOP EVENTS SECTION */}
        {ngoStats?.topEvents?.length > 0 && (
          <>
            <h4 style={{ marginTop: 20 }}>Top Events</h4>
            {ngoStats.topEvents.map((ev) => (
              <div
                key={ev.id}
                style={{
                  display: "flex",
                  gap: 12,
                  alignItems: "center",
                  padding: 8,
                  borderBottom: "1px solid #eee",
                }}
              >
                <img
                  src={ev.image_url || "https://via.placeholder.com/100x60"}
                  style={{
                    width: 100,
                    height: 60,
                    objectFit: "cover",
                    borderRadius: 6,
                  }}
                  alt="event"
                />
                <div>
                  <div style={{ fontWeight: 600 }}>{ev.title}</div>
                  <div style={{ color: "#666", fontSize: 13 }}>
                    Volunteers: {ev.volunteers_count}
                  </div>
                </div>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
